[Form]
public class METItemPackdetails extends FormRun  implements SysIFilterConsumerForm, SysIFilterEventHandler, METItemInquiryFilerProvider
{
    FormRun formRun;

}

/// <summary>
/// Event handler to react on a filter change.
/// </summary>
public void onFilterChanged()
{
    METInventItemOrderSetup_ds.research();
    METInventItemOrderSetup_ds.executeQuery();
}

/// <summary>
/// Initialize the filter consumer form.
