/// <summary>
/// Register the data source to which the filter should be applied.
/// </summary>
public void registerDatasourceOnQueryingEvent()
{
    METInventItemOrderSetup_ds.OnQueryExecuting += eventhandler(this.parmFilterFormQueryEventHandler().applyFilter);
}

/// <summary>
/// Initialize the filter consumer form.
/// </summary>
/// <returns>ItemId</returns>
public ItemId parmItemIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(ItemId));

}

/// <summary>
/// Initialize the inventory location filter.
/// </summary>
/// <returns>InventLocationId</returns>
public InventLocationId parminventoryLocationIdFilter()
{
    return SysFilterValueHelper::getFirstValueRecordFromFilterForType(this.parmSourceFilter(), SysFilterValueTypeEnum::String, extendedTypeNum(InventLocationId));
}

/// <summary>
/// Execute query
/// </summary>
public void executeQuery()
{
    ItemId                itemId              = formRun.parmitemId();
    QueryBuildDataSource  itemPackDetailsView = this.queryBuildDataSource();
    QueryBuildDataSource  inventDimDs = InventDim_ds.queryBuildDataSource();

    itemPackDetailsView.clearRanges();
    inventDimDs.clearRanges();

    if (itemId)
    {
        itemPackDetailsView.addRange(fieldNum(METInventItemOrderSetup, ItemId)).value(queryValue(itemId));
        itemPackDetailsView.addRange(fieldNum(METInventItemOrderSetup, ItemId)).status(RangeStatus::Locked);
    }

    InventLocationId inventLocationId = formRun.parminventoryLocationId();

    if (inventLocationId)
    {
        InventSiteId inventSiteId = InventLocation::find(inventLocationId).InventSiteId;
        inventDimDs.addRange(fieldNum(InventDim, InventSiteId)).value(queryValue(inventSiteId));
        inventDimDs.addRange(fieldNum(InventDim, InventSiteId)).status(RangeStatus::Locked);
    }

    super();
}
